  // HelpManual.js — 说明书正文（切片14）
  // 章节标题
  hm_title_start: '快速开始',
  hm_title_combat: '战斗操作',
  hm_title_world: '世界与位面',
  hm_title_dungeons: '地下城与 Boss',
